package com.nigson.commerce.inventory;
import java.util.*;
import java.math.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** No transaction creation/retry and no provider calls: all effects join caller's commerce transaction. */
public final class JdbcStockLedger implements StockLedger {
 private final JdbcTemplate jdbc;private final InventoryService events;private final AuditWriter audit;private final Clock clock;
 public JdbcStockLedger(JdbcTemplate jdbc,InventoryService events,AuditWriter audit,Clock clock){this.jdbc=jdbc;this.events=events;this.audit=audit;this.clock=clock;}
 private AuditValues.ActorKind actorKind(String subject){try{ApiValues.uuid(subject);return AuditValues.ActorKind.USER;}catch(Problem.Failure notParty){return AuditValues.ActorKind.SYSTEM;}}
 private record Balance(UUID id,UUID sku,UUID location,int scale,BigDecimal hand,BigDecimal reserved,BigDecimal allocated,long version){InventoryValues.Stock stock(){return new InventoryValues.Stock(sku,location,InventoryValues.wire(hand,scale),InventoryValues.wire(reserved,scale),InventoryValues.wire(allocated,scale),InventoryValues.wire(hand.subtract(reserved).subtract(allocated),scale),version);}}
 private Balance balance(UUID id){var rows=jdbc.query("SELECT b.*,s.quantity_scale FROM commerce.inventory_balance b JOIN commerce.sku s ON s.id=b.sku_id WHERE b.id=? FOR UPDATE OF b",(r,n)->new Balance(id,r.getObject("sku_id",UUID.class),r.getObject("location_id",UUID.class),r.getInt("quantity_scale"),r.getBigDecimal("on_hand"),r.getBigDecimal("reserved"),r.getBigDecimal("allocated"),r.getLong("version")),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private Map<String,Object> begin(UUID order,UUID command,String actor,UUID correlation){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");if(order==null||command==null||correlation==null)throw ApiValues.invalid();for(UUID id:List.of(order,command,correlation))ApiValues.uuid(id.toString());AuditValues.subject(actor);jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2000ms'");var rows=jdbc.queryForList("SELECT * FROM commerce.sales_order WHERE id=? FOR UPDATE",order);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"stock-command:"+command);return rows.getFirst();}
 private List<InventoryValues.Stock> replay(String type,UUID command,String hash){var rows=jdbc.queryForList("SELECT request_hash,response_body::text FROM commerce.idempotency_record WHERE principal_key='local-stock-ledger' AND operation=? AND request_key=?","STOCK-"+type,command.toString());if(rows.isEmpty())return null;if(!rows.getFirst().get("request_hash").equals(hash))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return List.of(EventCodec.JSON.readValue(rows.getFirst().get("response_body").toString(),InventoryValues.Stock[].class));}
 private void currentReferences(Collection<UUID> ids){var products=new TreeSet<UUID>(Comparator.comparing(UUID::toString));var skus=new TreeSet<UUID>(Comparator.comparing(UUID::toString));var locations=new TreeSet<UUID>(Comparator.comparing(UUID::toString));for(var id:ids){var rows=jdbc.queryForList("SELECT s.id,s.product_id,b.location_id FROM commerce.inventory_balance b JOIN commerce.sku s ON s.id=b.sku_id WHERE b.id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();products.add((UUID)row.get("product_id"));skus.add((UUID)row.get("id"));locations.add((UUID)row.get("location_id"));}for(UUID id:locations)if(jdbc.query("SELECT id FROM commerce.stock_location WHERE id=? AND active FOR SHARE",(r,n)->r.getObject(1,UUID.class),id).size()!=1)throw InventoryValues.rule();for(UUID id:products)if(jdbc.query("SELECT id FROM commerce.product WHERE id=? AND status='ACTIVE' AND deleted_at IS NULL FOR SHARE",(r,n)->r.getObject(1,UUID.class),id).size()!=1)throw InventoryValues.rule();for(UUID id:skus)if(jdbc.query("SELECT id FROM commerce.sku WHERE id=? AND active AND deleted_at IS NULL FOR SHARE",(r,n)->r.getObject(1,UUID.class),id).size()!=1)throw InventoryValues.rule();}
 private List<InventoryValues.Stock> finish(String type,UUID order,UUID command,String actor,String hash,List<InventoryValues.Stock> result){jdbc.update("INSERT INTO commerce.idempotency_record(id,created_by,updated_by,principal_key,operation,request_key,request_hash,state,response_status,response_body,resource_id,expires_at) VALUES (?,?,?,'local-stock-ledger',?,?,?,'SUCCEEDED',200,?::jsonb,?,?)",EventCodec.uuid7(clock.instant()),actor,actor,"STOCK-"+type,command.toString(),hash,EventCodec.JSON.writeValueAsString(result),order,java.sql.Timestamp.from(clock.instant().plusSeconds(86400)));return List.copyOf(result);}
 private String hash(UUID order,Object body){return EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("order",order,"body",body)));}
 private void maximum(int size){if(size<1||size>100)throw ApiValues.invalid();}
 private LinkedHashMap<UUID,Balance> locks(Collection<UUID> ids){maximum(ids.size());var result=new LinkedHashMap<UUID,Balance>();for(UUID id:ids.stream().sorted(Comparator.comparing(UUID::toString)).toList())result.put(id,balance(id));return result;}
 private InventoryValues.Stock change(Balance b,UUID order,String type,BigDecimal dh,BigDecimal dr,BigDecimal da,UUID line,String kind,String receipt,String reason,UUID command,String actor,UUID correlation){if(b.version==Long.MAX_VALUE)throw InventoryValues.rule();BigDecimal hand=b.hand.add(dh),reserved=b.reserved.add(dr),allocated=b.allocated.add(da);if(hand.signum()<0||reserved.signum()<0||allocated.signum()<0||hand.compareTo(reserved.add(allocated))<0||hand.compareTo(InventoryValues.MAX)>0)throw InventoryValues.rule();String key=type.equals("RETURN")?"RETURN:"+command+":"+line:type+":"+command+":"+b.id+(line==null?"":":"+line);
  jdbc.update("INSERT INTO commerce.inventory_movement(id,created_by,balance_id,order_id,operation_key,movement_type,delta_on_hand,delta_reserved,delta_allocated,reason,order_line_id,return_kind,receipt_reference) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,b.id,order,key,type,dh,dr,da,reason,line,kind,receipt);
  jdbc.update("UPDATE commerce.inventory_balance SET on_hand=?,reserved=?,allocated=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",hand,reserved,allocated,java.sql.Timestamp.from(clock.instant()),actor,b.id);var after=new Balance(b.id,b.sku,b.location,b.scale,hand,reserved,allocated,b.version+1).stock();audit.append(actor,actorKind(actor),AuditValues.Action.STOCK_TRANSITION,AuditValues.Resource.INVENTORY,b.id,correlation,AuditValues.Reason.RECONCILIATION,Map.of("version",b.version),Map.of("version",after.version()),null);events.event(b.id,after,actor,correlation);events.movement(type);return after;
 }
 public List<InventoryValues.Stock> reserve(UUID order,Map<UUID,String> quantities,Instant expiresAt,UUID command,String actor,UUID correlation){if(quantities==null)throw ApiValues.invalid();maximum(quantities.size());for(var entry:quantities.entrySet()){if(entry.getKey()==null)throw ApiValues.invalid();ApiValues.uuid(entry.getKey().toString());InventoryValues.quantity(entry.getValue(),3,false);}if(expiresAt==null)throw ApiValues.invalid();var state=begin(order,command,actor,correlation);String hash=hash(order,Map.of("quantities",quantities,"expiresAt",expiresAt));var previous=replay("RESERVE",command,hash);if(previous!=null)return previous;if(!Set.of("PENDING","PAYMENT_HOLD").contains(state.get("status"))||!expiresAt.isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  currentReferences(quantities.keySet());var balances=locks(quantities.keySet());var requested=new HashMap<UUID,BigDecimal>();var amounts=new HashMap<UUID,BigDecimal>();for(var b:balances.values()){var q=InventoryValues.quantity(quantities.get(b.id),b.scale,false);amounts.put(b.id,q);requested.merge(b.sku,q,BigDecimal::add);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.stock_location l JOIN commerce.sku s ON s.id=? JOIN commerce.product p ON p.id=s.product_id WHERE l.id=? AND l.active AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL)",Boolean.class,b.sku,b.location)))throw InventoryValues.rule();}
  var ordered=new HashMap<UUID,BigDecimal>();jdbc.query("SELECT sku_id,sum(quantity) q FROM commerce.order_line WHERE order_id=? GROUP BY sku_id LIMIT 101",(org.springframework.jdbc.core.RowCallbackHandler)r->ordered.put(r.getObject(1,UUID.class),r.getBigDecimal(2)),order);if(ordered.size()>100||!ordered.keySet().equals(requested.keySet())||ordered.entrySet().stream().anyMatch(e->e.getValue().compareTo(requested.get(e.getKey()))!=0))throw InventoryValues.rule();
  var result=new ArrayList<InventoryValues.Stock>();for(var b:balances.values()){BigDecimal q=amounts.get(b.id);var existing=jdbc.queryForList("SELECT id,status,quantity FROM commerce.inventory_reservation WHERE order_id=? AND balance_id=? FOR UPDATE",order,b.id);if(existing.isEmpty())jdbc.update("INSERT INTO commerce.inventory_reservation(id,created_by,updated_by,order_id,balance_id,quantity,status,expires_at) VALUES (?,?,?,?,?,?,'RESERVED',?)",EventCodec.uuid7(clock.instant()),actor,actor,order,b.id,q,java.sql.Timestamp.from(expiresAt));else{var old=existing.getFirst();if(!old.get("status").equals("RELEASED")||((BigDecimal)old.get("quantity")).compareTo(q)!=0||jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_movement WHERE order_id=? AND balance_id=? AND movement_type IN ('SETTLE','DISPATCH','RETURN')",Integer.class,order,b.id)!=0)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);jdbc.update("UPDATE commerce.inventory_reservation SET status='RESERVED',expires_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(expiresAt),java.sql.Timestamp.from(clock.instant()),actor,old.get("id"));}result.add(change(b,order,"RESERVE",BigDecimal.ZERO,q,BigDecimal.ZERO,null,null,null,"Owned order reservation",command,actor,correlation));}return finish("RESERVE",order,command,actor,hash,result);
 }
 private List<InventoryValues.Stock> transition(UUID order,String type,UUID command,String actor,UUID correlation){var state=begin(order,command,actor,correlation);String hash=hash(order,type);var previous=replay(type,command,hash);if(previous!=null)return previous;
  if(type.equals("SETTLE")){if(!state.get("payment_status").equals("PAID")||!Set.of("PAID","PROCESSING").contains(state.get("status"))||state.get("hold_reason")!=null||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_transaction t JOIN commerce.payment_attempt a ON a.id=t.attempt_id WHERE a.order_id=? AND a.state='SUCCEEDED' AND t.settled_amount>=? AND t.currency_code=? AND t.provider_mode=a.provider_mode)",Boolean.class,order,state.get("grand_total"),state.get("currency_code"))))throw InventoryValues.rule();}else if(!state.get("status").equals("CANCELLED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  var reservations=jdbc.queryForList("SELECT id,balance_id,quantity,status FROM commerce.inventory_reservation WHERE order_id=? ORDER BY balance_id LIMIT 101",order);maximum(reservations.size());var ids=reservations.stream().map(r->(UUID)r.get("balance_id")).toList();var balances=locks(ids);var result=new ArrayList<InventoryValues.Stock>();for(var r:reservations){if(!r.get("status").equals("RESERVED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);UUID id=(UUID)r.get("balance_id");var q=(BigDecimal)r.get("quantity");jdbc.update("UPDATE commerce.inventory_reservation SET status=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",type.equals("SETTLE")?"ALLOCATED":"RELEASED",java.sql.Timestamp.from(clock.instant()),actor,r.get("id"));result.add(change(balances.get(id),order,type,BigDecimal.ZERO,q.negate(),type.equals("SETTLE")?q:BigDecimal.ZERO,null,null,null,type.equals("SETTLE")?"Verified local settlement":"Cancelled order reservation release",command,actor,correlation));}return finish(type,order,command,actor,hash,result);
 }
 public List<InventoryValues.Stock> allocate(UUID order,UUID command,String actor,UUID correlation){return transition(order,"SETTLE",command,actor,correlation);}
 public List<InventoryValues.Stock> release(UUID order,UUID command,String actor,UUID correlation){return transition(order,"RELEASE",command,actor,correlation);}
 private List<InventoryValues.Stock> lines(UUID order,List<Line> input,ReturnKind kind,String receipt,String reason,UUID command,String actor,UUID correlation){if(input==null)throw ApiValues.invalid();maximum(input.size());for(var line:input){if(line==null||line.orderLineId()==null||line.balanceId()==null)throw ApiValues.invalid();ApiValues.uuid(line.orderLineId().toString());ApiValues.uuid(line.balanceId().toString());InventoryValues.quantity(line.quantity(),3,false);}var lines=input.stream().sorted(Comparator.comparing((Line line)->line.balanceId().toString()).thenComparing(line->line.orderLineId().toString())).toList();if(lines.stream().map(l->kind==null?l.balanceId()+":"+l.orderLineId():l.orderLineId().toString()).distinct().count()!=lines.size())throw ApiValues.invalid();String operation=kind==null?"DISPATCH":"RETURN";var state=begin(order,command,actor,correlation);String hash=hash(order,Map.of("lines",lines,"kind",kind==null?"DISPATCH":kind.name(),"receipt",receipt==null?"":receipt,"reason",reason));var previous=replay(operation,command,hash);if(previous!=null)return previous;
  if(kind==null&&(!Set.of("PAID","PROCESSING","SHIPPED").contains(state.get("status"))||!Set.of("PAID","PARTIALLY_REFUNDED").contains(state.get("payment_status"))||state.get("hold_reason")!=null))throw InventoryValues.rule();if(kind==ReturnKind.UNSHIPPED_CANCEL&&!Set.of("CANCELLED","REFUNDING","REFUNDED").contains(state.get("status")))throw InventoryValues.rule();
  var balances=locks(lines.stream().map(Line::balanceId).distinct().toList());var results=new LinkedHashMap<UUID,InventoryValues.Stock>();
  for(var line:lines){var b=balances.get(line.balanceId());var amounts=jdbc.query("SELECT quantity FROM commerce.order_line WHERE id=? AND order_id=? AND sku_id=?",(r,n)->r.getBigDecimal(1),line.orderLineId(),order,b.sku);if(amounts.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=InventoryValues.quantity(line.quantity(),b.scale,false);
   BigDecimal dispatched=jdbc.queryForObject("SELECT coalesce(-sum(delta_on_hand),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='DISPATCH'",BigDecimal.class,order,line.orderLineId());BigDecimal returned=jdbc.queryForObject("SELECT coalesce(sum(delta_on_hand),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='RETURN' AND return_kind='PHYSICAL_RETURN'",BigDecimal.class,order,line.orderLineId());BigDecimal cancelled=jdbc.queryForObject("SELECT coalesce(-sum(delta_allocated),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='RETURN' AND return_kind='UNSHIPPED_CANCEL'",BigDecimal.class,order,line.orderLineId());
   BigDecimal limit=kind==ReturnKind.PHYSICAL_RETURN?dispatched.subtract(returned):amounts.getFirst().subtract(dispatched).subtract(cancelled);if(q.compareTo(limit)>0)throw InventoryValues.rule();
   var reservations=jdbc.queryForList("SELECT id,status,quantity FROM commerce.inventory_reservation WHERE order_id=? AND balance_id=? FOR UPDATE",order,b.id);if(reservations.size()!=1||kind!=ReturnKind.PHYSICAL_RETURN&&!reservations.getFirst().get("status").equals("ALLOCATED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
   InventoryValues.Stock result=change(b,order,kind==null?"DISPATCH":"RETURN",kind==null?q.negate():kind==ReturnKind.PHYSICAL_RETURN?q:BigDecimal.ZERO,BigDecimal.ZERO,kind==ReturnKind.PHYSICAL_RETURN?BigDecimal.ZERO:q.negate(),line.orderLineId(),kind==null?null:kind.name(),receipt,reason,command,actor,correlation);results.put(b.id,result);balances.put(b.id,balance(b.id));
   if(kind!=ReturnKind.PHYSICAL_RETURN){BigDecimal consumed=jdbc.queryForObject("SELECT coalesce(-sum(delta_allocated),0) FROM commerce.inventory_movement WHERE order_id=? AND balance_id=? AND (movement_type='DISPATCH' OR movement_type='RETURN' AND return_kind='UNSHIPPED_CANCEL')",BigDecimal.class,order,b.id);var reservation=reservations.getFirst();if(consumed.compareTo((BigDecimal)reservation.get("quantity"))>0)throw InventoryValues.rule();BigDecimal dispatchedForBalance=jdbc.queryForObject("SELECT coalesce(-sum(delta_on_hand),0) FROM commerce.inventory_movement WHERE order_id=? AND balance_id=? AND movement_type='DISPATCH'",BigDecimal.class,order,b.id);String target=consumed.compareTo((BigDecimal)reservation.get("quantity"))==0?(dispatchedForBalance.signum()>0?"DISPATCHED":"RELEASED"):"ALLOCATED";jdbc.update("UPDATE commerce.inventory_reservation SET status=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",target,java.sql.Timestamp.from(clock.instant()),actor,reservation.get("id"));}
  }
  return finish(operation,order,command,actor,hash,new ArrayList<>(results.values()));
 }
 public List<InventoryValues.Stock> dispatch(UUID order,List<Line> lines,UUID command,String actor,UUID correlation){return lines(order,lines,null,null,"Paid unheld order dispatch",command,actor,correlation);}
 public List<InventoryValues.Stock> returned(UUID order,List<Line> lines,ReturnKind kind,String receipt,String reason,UUID command,String actor,UUID correlation){if(kind==null||receipt==null||!receipt.matches("[A-Za-z0-9][A-Za-z0-9:_-]{0,119}")||reason==null||reason.strip().length()<10||reason.length()>500||reason.codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT))throw ApiValues.invalid();return lines(order,lines,kind,receipt,reason,command,actor,correlation);}
}
